js:
frappe.ready(function() {
    if (window.location.pathname === "/job_application/new") {
        const video_html = `
            <div style="margin-bottom: 20px; max-width: 800px; margin-left: auto; margin-right: auto;">
                <h3>Please watch this before applying</h3>
                <iframe width="100%" height="400" 
                    src="https://www.youtube.com/embed/1F_2tA8ZvAE" 
                    frameborder="0" allowfullscreen>
                </iframe>
            </div>
        `;

        // Inject video inside .web-form container
        $('.web-form').prepend(video_html);
    }
});

